# LF5/LF6 added exact version-dispatch guards after LL9R. Include their paths
# so older freeze callers pass them through the v2 SHA guard before applying
# the historical LL9R reversal below.
from .v2_projection import EXPECTED as _V2_FILES
for _relative in _V2_FILES:
    REPLACEMENTS.setdefault(_relative, [])


def project(relative, text):
    from .v2_projection import project as v2_source
    text = v2_source(relative, text)
    for change in reversed(REPLACEMENTS.get(relative, ())):
        if text.count(change['after']) != change['count']:
            raise ValueError('unrecognized LL9R source repair: ' + relative)
        text = text.replace(change['after'], change['before'])
    return text
